code='''from collections import Counter, deque

def transform(grid):
    """Fill enclosed pockets of the dominant background color with 4."""
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    bg=Counter(v for row in g for v in row).most_common(1)[0][0]
    outside=set()
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==bg and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==bg and (r,c) not in outside:
                outside.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and (nr,nc) not in outside:
                outside.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and (r,c) not in outside:
                g[r][c]=4
    return g
'''
